import type { MetadataRoute } from 'next'

const SITE = process.env.NEXT_PUBLIC_SITE_URL ?? 'https://mudderfuger.ai'

/**
 * robots.txt — generated by Next's App Router at /robots.txt
 *
 * NOTE: /products/* is deliberately NOT disallowed here. Those URLs open a
 * product's details on the home page (Snipcart, which also fetched them, is
 * gone since 2026-11-08). robots.txt Disallow PREVENTS de-indexing: a blocked
 * URL can't be crawled, so Google never sees the `noindex` and the URL can sit
 * in the index as a bare listing. The noindex lives in products/layout.tsx,
 * and crawlers must be able to reach it to obey it.
 */
export default function robots(): MetadataRoute.Robots {
  return {
    rules: {
      userAgent: '*',
      allow: '/',
    },
    sitemap: `${SITE}/sitemap.xml`,
    host: SITE,
  }
}
